<?php
require_once __DIR__.'/../includes/verificar_sesion.php';$roles_permitidos=['administrador'];require_once __DIR__.'/../includes/verificar_rol.php';require_once __DIR__.'/../config/conexion.php';$errores=[];if($_SERVER['REQUEST_METHOD']==='POST'){$id_solicitud=(int)$_POST['id_solicitud'];$id_especialista=(int)$_POST['id_especialista'];$q=$pdo->prepare('SELECT estado FROM solicitudes WHERE id_solicitud=?');$q->execute([$id_solicitud]);$estado=$q->fetchColumn();$q=$pdo->prepare('SELECT id_reparacion FROM reparaciones WHERE id_solicitud=?');$q->execute([$id_solicitud]);if($estado!=='Aceptada')$errores[]='Solo se pueden asignar solicitudes con cotización aceptada.';elseif($q->fetch())$errores[]='Esta solicitud ya tiene una reparación asignada.';else{$q=$pdo->prepare('INSERT INTO reparaciones (id_solicitud,id_especialista,estado) VALUES (?,?,"Pendiente")');$q->execute([$id_solicitud,$id_especialista]);$id_reparacion=(int)$pdo->lastInsertId();registrar_historial($pdo,$id_reparacion,null,'Pendiente','Reparación creada y asignada al especialista.',$_SESSION['usuario']['id_usuario']);establecer_mensaje('exito','Especialista asignado correctamente.');redirigir('asignaciones.php');}}$solicitudes=$pdo->query("SELECT s.*,u.nombre AS cliente,c.costo_total FROM solicitudes s JOIN usuarios u ON u.id_usuario=s.id_cliente JOIN cotizaciones c ON c.id_solicitud=s.id_solicitud LEFT JOIN reparaciones r ON r.id_solicitud=s.id_solicitud WHERE s.estado='Aceptada' AND r.id_reparacion IS NULL ORDER BY s.fecha_solicitud")->fetchAll();$especialistas=$pdo->query("SELECT id_usuario,nombre FROM usuarios WHERE rol='especialista' AND estado='Activo' ORDER BY nombre")->fetchAll();$asignadas=$pdo->query("SELECT r.*,s.marca,s.modelo,u.nombre AS especialista,c.nombre AS cliente FROM reparaciones r JOIN solicitudes s ON s.id_solicitud=r.id_solicitud JOIN usuarios u ON u.id_usuario=r.id_especialista JOIN usuarios c ON c.id_usuario=s.id_cliente ORDER BY r.id_reparacion DESC")->fetchAll();$titulo_pagina='Asignaciones';$ruta_base='../';require_once __DIR__.'/../includes/encabezado.php';
?><div class="cabecera-panel"><div><span class="etiqueta">EQUIPO TÉCNICO</span><h1>Asignaciones</h1><p>Asigna cada servicio aceptado a un especialista disponible.</p></div></div><?php if($errores): ?><div class="alerta alerta-error"><?= escapar(implode(' ',$errores)) ?></div><?php endif; ?><section class="rejilla-dos"><div class="tarjeta"><h3>Solicitudes listas para asignar</h3><?php if(!$solicitudes): ?><div class="vacio">No hay solicitudes pendientes de asignación.</div><?php else: foreach($solicitudes as $s): ?><div class="fila-detalle"><div><strong>#<?= $s['id_solicitud'] ?> · <?= escapar($s['marca'].' '.$s['modelo']) ?></strong><br><small><?= escapar($s['cliente']) ?> · $<?= number_format($s['costo_total'],2) ?></small></div><form method="post" class="acciones"><input type="hidden" name="id_solicitud" value="<?= $s['id_solicitud'] ?>"><select name="id_especialista" required><option value="">Especialista...</option><?php foreach($especialistas as $e): ?><option value="<?= $e['id_usuario'] ?>"><?= escapar($e['nombre']) ?></option><?php endforeach; ?></select><button class="boton boton-pequeno" type="submit">Asignar</button></form></div><?php endforeach; endif; ?></div><div class="tarjeta"><h3>Reparaciones asignadas</h3><?php foreach($asignadas as $r): ?><div class="fila-detalle"><div><strong>#<?= $r['id_reparacion'] ?> · <?= escapar($r['marca'].' '.$r['modelo']) ?></strong><br><small><?= escapar($r['especialista']) ?></small></div><span class="<?= estado_clase($r['estado']) ?>"><?= escapar($r['estado']) ?></span></div><?php endforeach; ?></div></section><?php require_once __DIR__.'/../includes/pie.php'; ?>

